#include <iostream>
#include <vector>
#include <algorithm>
#include <numeric>

using namespace std;

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    sort(a.rbegin(), a.rend()); // 降序
    long long total = 0;
    for (long long x : a) total += x;
    long long my_sum = 0;
    int taken = 0;
    for (long long x : a) {
        my_sum += x;
        taken++;
        // BUG: 应为严格大于 my_sum > total - my_sum，此处误用 >= 
        if (my_sum >= total - my_sum) break;
    }
    cout << taken << "\n";
    return 0;
}
